			function sprtInstComboIndexCheck() {
			    
			    // 데이터 변경사항이 없을시 "변경된 데이터가 없습니다" 출력
			    if (!util.FreeForm.isModified(app, "grpBoardDtl", "MSG")) return false;
			    
			    // 그룹 내 컬럼 유효성 체크
			    if (!util.validate(app, "grpBoardDtl")) return false;
			    
			    // *** 직접입력관련 정책 확인 필요.
			    
			    // 지원기관 콤보 선택 값 체크
			    var selectedComboIdx = util.DataSet.getValue(app, "dsForm", 0, "LINK_SPRT_INST_CHC_TYPE_CD");
			    
			    // 지원기관 구분 select box 값이 직접입력 or 기관검색 에 따라 로직 처리
			    //LINK_SPRT_INST_CHC_TYPE_CD
			    if (selectedComboIdx == "01") {
			        
			        // 직접입력인 경우 입력한 기관번호 > 통합기관 조회 
			        // 있는 경우 해당 기관번호 추출 후 저장
			        // 없는 경우 직접입력한 기관정보가 없습니다. alert 처리
			        
			        var searchInstNm = util.DataSet.getValue(app, "dsForm", 0, "LINK_SPRT_INST_NM");
			        
			        voDmSearchInstInfoParam = app.lookup("dmSearchInstInfo");
			        voDmSearchInstInfoParam.clear();
			        voDmSearchInstInfoParam.setValue("INPUT_INST_NM", searchInstNm);
			        
			        // 직접일력한 기관명 존재 여부 조회
			        doSprtInstSearch();
			        
			    } else {
			        
			        // 첨부 파일 저장 > 저장 후 첨부파일 일련번호가 넘어옴. 바인딩되어있음.
			        app.lookup("cmnsinglefileupload1").send(doSave);
			        
			    }
			    
			}

			function doSprtInstSearch() {
			    
			    util.Submit.send(app, "subInstSearch", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            // 등록, 수정, 삭제 리턴 후 리스트 재조회
			            
			            // 지원기관 콤보 선택 값 체크
			            var resultYn = util.DataMap.getValue(app, "dmSearchInstInfo", "RESULT_YN");
			            
			            if (resultYn == "N") {
			                
			                util.Msg.alert(app, "직접 입력한 지원기관 정보가 없습니다.");
			                
			            } else if (resultYn == "Y") {
			                
			                // 같은 기관명으로 1개 이상이 조회될 수 있음. > 조회된 데이터에 기관번호, 기관이름은 모두 동일
			                // 여러개일 경우 데이터 0번째 기관번호, 기관이름 임시 셋팅 - 
			                // 추후 정책 확인 필요.
			                // as-is 의 경우 직접입력시 기관조회로직은 없음.
			                // as-is 의 경우 기관 찾기시 같은 이름에 기관여러개 조회됨.
			                // 기관구분, 전화번호, 서비스내용은 다를수 있지만 등록시 동일한 기관명, 기관번로만 등록함. 
			                
			                util.DataSet.setValue(app, "dsForm", 0, "LINK_RESRCE_INST_NO", util.DataSet.getValue(app, "dsSearchInstInfoList", 0, "SEARCH_INST_NO"));
			                util.DataSet.setValue(app, "dsForm", 0, "LINK_SPRT_INST_NM", util.DataSet.getValue(app, "dsSearchInstInfoList", 0, "SEARCH_INST_NM"));
			                
			                // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			                util.Control.redraw(app, "grp1");
			                
			                // 등록, 수정, 삭제 공용 사용 
			                doSave();
			                
			            }
			            
			        }
			    });
			    
			}

			/**
			 * 상세 데이터 조회 서브미션 호출
			 * @param psStatus - 조회 상태(저장 후 조회인 경우에는 'save' 구분값 넘김)
			 */
			function doDetail(psStatus) {
			    
			    //상세 조회 서브미션 호출
			    util.Submit.send(app, "subSave", function(pbSuccess) {
			        if (pbSuccess) {
			            if (psStatus == "save") {
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            } else {
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			        }
			        
			        // 저장한 첨부파일 가져옴. 공통 첨부 기능에서 로직 처리됨.
			        app.lookup("cmnsinglefileupload1").getFiles();
			        
			        // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			        util.Control.redraw(app, "grpBoardDtl");
			        
			    });
			}

			/**
			 * 등록, 수정, 삭제 데이터 저장 서브미션 호출
			 */
			function doSave() {
			    
			    // 첨부 파일
			    //app.lookup("cmnsinglefileupload1").getFiles();
			    var vcfld = app.lookup("cmnsinglefileupload1");
			    
			    if (type == "UPDATE") {
			        // 수정
			        voDmDtlParam.setValue("VIEW_TYPE", "u");
			        // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			        util.Control.redraw(app, "grpBoardDtl");
			        
			    } else if (type == "DELETE") {
			        
			        // 삭제
			        voDmDtlParam.setValue("VIEW_TYPE", "d");
			        
			    }
			    
			    // 저장 서브미션 호출
			    util.Submit.send(app, "subSave", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            // 등록, 수정, 삭제 리턴 후 리스트 재조회
			            app.close("save");
			            
			        }
			    });
			    
			}

			/**
			 * CRUD 권한에 따른 화면 구성
			 ** @param {"CREATE" | "READ" | "UPDATE"} type 게시글 상세 조회 타입
			 */
			function setDtlCrud(type, taskwkSeCd) {
			    
			    var vcGrp = app.lookup("grp1");
			    var voGrpLayout = vcGrp.getLayout();
			    
			    if (type == "CREATE") {
			        
			        // 등록
			        
			        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete", "btnRestore"]);
			        util.Control.setVisible(app, true, ["btnSave", "btnClose"]);
			        
			        util.Control.setVisible(app, true, ["cmb1", "ipb1", "sipb2"]);
			        
			        util.Control.setReadOnly(app, false, "grpBoardDtl");
			        
			    } else if (type == "READ") {
			        
			        // 상세
			        
			        voGrpLayout.setColumnVisible(0, false);
			        voGrpLayout.setColumnVisible(1, true);
			        voGrpLayout.setColumnVisible(2, false);
			        
			        util.Control.setVisible(app, false, ["btnSave", "btnRestore"]);
			        util.Control.setVisible(app, true, ["btnUpdate", "btnDelete", "btnClose"]);
			        
			        util.Control.setVisible(app, false, ["cmb1", "sipb2"]);
			        util.Control.setVisible(app, true, ["ipb1"]);
			        
			        util.Control.setReadOnly(app, true, "grpBoardDtl");
			        
			    } else if (type == "UPDATE") {
			        
			        // 수정
			        
			        // 지원기관 콤보박스 선택 값에 따라 활성 / 비활성
			        // 조회해온 상세 데이터 콤보박스 value 가 직접입력 / 기관 검색 인지도 한번더 체크해줘야함.
			        
			        voGrpLayout.setColumnVisible(0, true);
			        var vsVal = app.lookup("cmb1").value;
			        
			        if (vsVal == "01") {
			            voGrpLayout.setColumnVisible(1, true);
			            voGrpLayout.setColumnVisible(2, false);
			        } else {
			            voGrpLayout.setColumnVisible(1, false);
			            voGrpLayout.setColumnVisible(2, true);
			        }
			        
			        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete"]);
			        util.Control.setVisible(app, true, ["btnSave", "btnRestore", "btnClose"]);
			        
			        util.Control.setVisible(app, true, ["cmb1", "ipb1", "sipb2"]);
			        
			        util.Control.setReadOnly(app, false, "grpBoardDtl");
			        
			    }
			    
			    // 만약 지원사업 부분도 벨리데이션 체크해야하는 경우는 
			    // 일반 속성에 required 를 false로 스크립트 처리해줘야함.
			    
			    // 업무구분(해당업무 진입 메뉴 구분) > 변경될 수 있음. 정책 최종 확인 필요.
			    // 청소년상담복지센터(CYS-NET : U02), 학교밖청소년지원센터(꿈드림 : U03), 청소년쉼터(청소년쉼터 행정지원시스템 : U04)
			    if (taskwkSeCd == "U03") {
			        
			        app.lookup("grpBoardDtl").getLayout().setRowVisible(2, true);
			        
			    } else {
			        
			        app.lookup("grpBoardDtl").getLayout().setRowVisible(2, false);
			        
			    }
			    
			}

			/**
			 * 연계자원 기관 선택 팝업 호출
			 */
			function openLinkResrceInstChcPopup() {
			    
			    var voRowData = null;
			    
			    var popTitle = "연계자원기관검색";
			    
			    var initValue = {
			        //        searchKey : voRowData,
			        //        type : type,
			        //        taskwkSeCd : taskwkSeCd
			    }
			    
			    util.Dialog.open(app, "app/itgcms/extrnltaskwk/extrnlsprtactvt/LinkResrceInstChcPopup", popTitle, 740, 560, function( /*cpr.events.CUIEvent*/ e) {
			        
			        /*
			         * 다이얼로그 close 이벤트 핸들러(닫기 동작시 반환되는 값에 대한 처리)
			         * 다이얼로그가 이미 닫혀진 상태이기 때문에 다이얼로그 관련 이벤트리스너는 발생하지 않습니다.
			         */
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnValue = dialog.returnValue;
			        
			        /*
			         * returnValue 처리
			         * returnValue가 단일값을 경우 그대로 사용할 수 있으며, JSON 데이터일 경우 key값을 통해 value를 받을 수 있습니다. 
			         */
			        if (!ValueUtil.isNull(returnValue)) {
			            
			            util.DataSet.setValue(app, "dsForm", 0, "LINK_RESRCE_INST_NO", returnValue["selectedInstNo"]);
			            util.DataSet.setValue(app, "dsForm", 0, "LINK_SPRT_INST_NM", returnValue["selectedInstNm"]);
			            
			            // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			            util.Control.redraw(app, "grp1");
			            
			        }
			        
			    }, initValue);
			}

