			/*
			 * 루트 컨테이너에서 load 이벤트 발생 시 호출.
			 * 앱이 최초 구성된후 최초 랜더링 직후에 발생하는 이벤트 입니다.
			 */
			function onBodyLoad( /* cpr.events.CEvent */ e) {
			    
			    var voInitValue = app.getHostProperty("initValue");
			    
			    // 화면 타입 > 등록, 수정, 삭제
			    type = voInitValue["type"];
			    
			    // 업무구분(해당업무 진입 메뉴 구분) > 변경될 수 있음. 정책 최종 확인 필요.
			    // 청소년상담복지센터(CYS-NET : U02), 학교밖청소년지원센터(꿈드림 : U03), 청소년쉼터(청소년쉼터 행정지원시스템 : U04)
			    taskwkSeCd = voInitValue["taskwkSeCd"];
			    
			    // 상세일 경우 조회 key
			    searchKey = voInitValue["searchKey"];
			    
			    voDmDtlParam = app.lookup("dmDetail");
			    
			    /*공통 서비스 호출 (공통코드, 현재일자 등)*/
			    util.Submit.send(app, "subOnload", function(pbSuccess) {
			        
			        if (pbSuccess) {
			            
			            // 서버 년월일 기본값 적용(현재년도)
			            var vsSysDate = util.DataMap.getValue(app, "dmTime", "strSysDate");
			            
			            // 지원기관(직접입력, 기관찾기) select box 초기값 셋팅
			            //util.Control.setValue(app, "cmb2", "00");
			            app.lookup("cmb1").selectItem(0);
			            
			            voDmDtlParam.clear();
			            
			            // 화면 처리
			            if (type == "CREATE") { // 신규 등록
			                
			                // 연계지원일자 기본값 적용(현재년도)
			                var insertRowData = {
			                    LINK_SPRT_YMD: vsSysDate
			                }
			                
			                app.lookup("dsForm").addRowData(insertRowData);
			                
			                // 등록, 상세, 수정, 삭제 타입
			                voDmDtlParam.setValue("VIEW_TYPE", "i");
			                
			                setDtlCrud(type, taskwkSeCd);
			                
			            } else if (type == "READ") { // 상세 진입
			                
			                // 상세인 경우 실제 데이터 조회
			                voDmDtlParam.setValue("VIEW_TYPE", "r");
			                voDmDtlParam.setValue("GR_LINK_SPRT_MNG_NO", searchKey);
			                
			                // 상세 조회
			                doDetail();
			                
			                setDtlCrud(type, taskwkSeCd);
			                
			            }
			            
			            // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			            util.Control.redraw(app, "grpBoardDtl");
			            
			        }
			        
			    });
			    
			}

			/*
			 * "닫기" 버튼(btnClose)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnCloseClick(e) {
			    var btnClose = e.control;
			    
			    // return value 없음
			    app.close();
			}

			/*
			 * "수정" 버튼(btnUpdate)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnUpdateClick(e) {
			    var btnUpdate = e.control;
			    
			    type = "UPDATE";
			    setDtlCrud(type, taskwkSeCd);
			    
			}

			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e) {
			    var btnSave = e.control;
			    
			    util.Msg.confirm(app, "CRM-M001", null, function() {
			        sprtInstComboIndexCheck();
			    });
			    
			}

			/*
			 * 콤보 박스에서 selection-change 이벤트 발생 시 호출.
			 * ComboBox Item을 선택하여 선택된 값이 저장된 후에 발생하는 이벤트.
			 */
			function onCmb1SelectionChange2(e) {
			    var cmb1 = e.control;
			    
			    util.DataSet.setValue(app, "dsForm", 0, "LINK_RESRCE_INST_NO", "");
			    util.DataSet.setValue(app, "dsForm", 0, "LINK_SPRT_INST_NM", "");
			    
			    // 그룹 갱신(데이터 변경이 있으면 갱신을 해줘야 적용됨.)
			    util.Control.redraw(app, "grp1");
			    
			    var vsVal = cmb1.value;
			    var vcGrp = app.lookup("grp1");
			    var voGrpLayout = vcGrp.getLayout();
			    
			    if (vsVal == "01") {
			        
			        voGrpLayout.setColumnVisible(1, true);
			        voGrpLayout.setColumnVisible(2, false);
			    } else {
			        voGrpLayout.setColumnVisible(1, false);
			        voGrpLayout.setColumnVisible(2, true);
			    }
			}

			/*
			 * "취소" 버튼(btnRestore)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnRestoreClick(e) {
			    var btnRestore = e.control;
			    
			    type = "READ";
			    setDtlCrud(type, taskwkSeCd);
			    
			}

